pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(this));

        // Deploy a helper that always succeeds on calls
        SuccessAlways helper = new SuccessAlways();

        bool referenceResult;
        try c.transfer(from, address(helper), _tos, v) returns (bool res) {
            referenceResult = res;
        } catch {
            // If it reverts, the property is vacuously true for that input
            assertTrue(true);
            return;
        }

        // For inputs where reference does not revert, assert that it returns true
        assertTrue(referenceResult == true);
    }
}

contract SuccessAlways {
    fallback() external {}
}

